export function applyDiscount(total, pct) {
  return total - total * (pct / 100);
}

export function cartTotal(lines, discountPct) {
  const sum = lines.reduce((s, l) => s + l.price * l.qty, 0);
  return applyDiscount(sum, discountPct);
}
